import unittest

def calculate_interest(principal: float, rate: float, time: float) -> float:
    """
    Calculate the simple interest given the principal amount, interest rate, and time in years.

    :param principal: The principal amount of the loan.
    :param rate: The annual interest rate (as a decimal).
    :param time: The time period in years.
    :return: The calculated simple interest.
    """
    return principal * rate * time

class TestCalculateInterest(unittest.TestCase):
    def test_positive_values(self):
        self.assertEqual(calculate_interest(1000, 0.05, 2), 100.0)

    def test_zero_principal(self):
        self.assertEqual(calculate_interest(0, 0.05, 2), 0)

    def test_zero_rate(self):
        self.assertEqual(calculate_interest(1000, 0, 2), 0)

    def test_zero_time(self):
        self.assertEqual(calculate_interest(1000, 0.05, 0), 0)

    def test_single_unit_interest(self):
        self.assertEqual(calculate_interest(1, 1, 1), 1)

    def test_large_numbers(self):
        self.assertEqual(calculate_interest(1000000, 0.25, 10), 2500000.0)

    def test_negative_principal(self):
        self.assertEqual(calculate_interest(-1000, 0.05, 2), -100.0)

    def test_negative_rate(self):
        self.assertEqual(calculate_interest(1000, -0.05, 2), -100.0)

    def test_negative_time(self):
        self.assertEqual(calculate_interest(1000, 0.05, -2), -100.0)

    def test_decimal_values(self):
        self.assertAlmostEqual(calculate_interest(1234.56, 0.789, 3.456), 3207.2036736, places=7)

    def test_mixed_negative_positive(self):
        self.assertEqual(calculate_interest(-1000, -0.05, 2), 100.0)

if __name__ == '__main__':
    unittest.main()
