def translate_number(n):
    """
    Convert a non-negative integer less than 1000 to its English words representation.

    Parameters:
    n (int): The integer to convert (0 ≤ n < 1000).

    Returns:
    str: The English words representation of the integer.
    """
    if n == 0:
        return "zero"

    def one(n):
        """
        Convert a single digit number to its English word.

        Parameters:
        n (int): The digit to convert (1 ≤ n ≤ 9).

        Returns:
        str: The English word for the digit.
        """
        switcher = {
            1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
            6: "six", 7: "seven", 8: "eight", 9: "nine"
        }
        return switcher.get(n, "")

    def two_less_20(n):
        """
        Convert a number between 10 and 19 to its English words.

        Parameters:
        n (int): The number to convert (10 ≤ n ≤ 19).

        Returns:
        str: The English words for the number.
        """
        switcher = {
            10: "ten", 11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
            15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen"
        }
        return switcher.get(n, "")

    def ten(n):
        """
        Convert a multiple of ten to its English word.

        Parameters:
        n (int): The digit to convert (2 ≤ n ≤ 9).

        Returns:
        str: The English word for the multiple of ten.
        """
        switcher = {
            2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
            6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety"
        }
        return switcher.get(n, "")

    def two(n):
        """
        Convert a two-digit number to its English words.

        Parameters:
        n (int): The number to convert (0 ≤ n < 100).

        Returns:
        str: The English words for the number.
        """
        if not n:
            return ''
        elif n < 10:
            return one(n)
        elif n < 20:
            return two_less_20(n)
        else:
            tenner = n // 10
            rest = n - tenner * 10
            return ten(tenner) + (' ' + one(rest) if rest else '')

    def three(n):
        """
        Convert a three-digit number to its English words.

        Parameters:
        n (int): The number to convert (0 ≤ n < 1000).

        Returns:
        str: The English words for the number.
        """
        hundred = n // 100
        rest = n - hundred * 100
        if hundred and rest:
            return one(hundred) + ' hundred ' + two(rest)
        elif not hundred and rest:
            return two(rest)
        elif hundred and not rest:
            return one(hundred) + ' hundred'

    return three(n)
