def list_to_string(lst):
    """
    Convert a list of integers into a string representation with elements separated by hyphens.

    :param lst: List of integers
    :return: String representation of the list with elements separated by hyphens
    """
    if not lst:
        return ""
    elif len(lst) == 1:
        return str(lst[0])
    else:
        return str(lst[0]) + '-' + list_to_string(lst[1:])
