def closest_to_zero(numbers):
    """
    Finds the integer in the list that is closest to zero.
    If there are multiple integers with the same absolute value, returns the smallest one.

    :param numbers: List of integers
    :return: Integer closest to zero
    """
    closest = None
    for number in numbers:
        if closest is None:
            closest = number
        else:
            current_abs = number if number > 0 else -number
            closest_abs = closest if closest > 0 else -closest
            if current_abs < closest_abs:
                closest = number
            elif current_abs == closest_abs:
                if number < closest:
                    closest = number
    return closest
```

