def largestPowerOfPrime(n, p):
    """
    Calculates the largest power of a prime number p that divides n.

    :param n: int, the number to be divided
    :param p: int, the prime number
    :return: int, the largest power of p that divides n
    """
    if n % p != 0:
        return 0
    else:
        return 1 + largestPowerOfPrime(n // p, p)
