def power_of_two(n: int) -> int:
    """
    Computes the n-th power of 2 using recursion and bitwise operations.
    Returns 1 if n is 0 or less.

    :param n: The exponent to which 2 is raised.
    :return: The result of 2 raised to the power of n.
    """
    if n <= 0:
        return 1
    else:
        return (power_of_two(n - 1) << 1)
