class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, item, quantity=1):
        """
        Adds a specified quantity of an item to the inventory.
        If the item already exists, increases its quantity.
        """
        if item in self.items:
            self.items[item] += quantity
        else:
            self.items[item] = quantity
        print(f"Added {quantity} {item}(s).")

    def remove_item(self, item, quantity=1):
        """
        Removes a specified quantity of an item from the inventory.
        Prints an error message if the item does not exist or if the specified quantity exceeds the available quantity.
        """
        if item not in self.items:
            print(f"Error: {item} does not exist in the inventory.")
        elif self.items[item] < quantity:
            print(f"Error: Not enough {item} in the inventory to remove {quantity}.")
        elif self.items[item] == quantity:
            del self.items[item]
            print(f"Removed all {item}(s) from the inventory.")
        else:
            self.items[item] -= quantity
            print(f"Removed {quantity} {item}(s).")

    def list_items(self):
        """
        Lists all items in the inventory along with their quantities.
        Prints a message if the inventory is empty.
        """
        if not self.items:
            print("Inventory is empty.")
        else:
            print("Inventory:")
            for item, quantity in self.items.items():
                print(f"- {item}: {quantity}")

