import heapq

class ListAnalyzer:
    def __init__(self, numbers):
        """Initialize the object with a given list of integers."""
        if not isinstance(numbers, list):
            raise ValueError("Input should be a list of integers.")
        if not all(isinstance(n, int) for n in numbers):
            raise ValueError("All elements in the list should be integers.")
        self.numbers = numbers

    def find_k_smallest(self, k):
        """Find the k smallest elements in the list."""
        if not isinstance(k, int) or k < 0:
            raise ValueError("k should be a non-negative integer.")
        if k > len(self.numbers):
            raise ValueError("k should not be greater than the number of elements in the list.")
        return heapq.nsmallest(k, self.numbers)

    def find_k_largest(self, k):
        """Find the k largest elements in the list."""
        if not isinstance(k, int) or k < 0:
            raise ValueError("k should be a non-negative integer.")
        if k > len(self.numbers):
            raise ValueError("k should not be greater than the number of elements in the list.")
        return heapq.nlargest(k, self.numbers)
