def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_square(n):
    """Check if a number is a perfect square."""
    if n < 0:
        return False
    root = int(n**0.5)
    return root * root == n

def generate_url(user_id, post_id):
    """Generate the URL for a specific resource in the API."""
    base_url = "https://api.example.com"
    version = "v1"
    resource = f"/users/{user_id}/posts/{post_id}"

    if not is_prime(user_id) or not is_perfect_square(post_id):
        return ""

    return f"{base_url}/{version}{resource}"
