class TreeNode:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def get_height(self, root):
        """Return the height of the AVL tree rooted at 'root'."""
        if not root:
            return 0
        return root.height

    def get_balance(self, root):
        """Return the balance factor of the AVL tree rooted at 'root'."""
        if not root:
            return 0
        return self.get_height(root.left) - self.get_height(root.right)

    def right_rotate(self, y):
        """Perform a right rotation on the subtree rooted at 'y'."""
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        y.height = max(self.get_height(y.left), self.get_height(y.right)) + 1
        x.height = max(self.get_height(x.left), self.get_height(x.right)) + 1

        return x

    def left_rotate(self, x):
        """Perform a left rotation on the subtree rooted at 'x'."""
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        x.height = max(self.get_height(x.left), self.get_height(x.right)) + 1
        y.height = max(self.get_height(y.left), self.get_height(y.right)) + 1

        return y

    def insert(self, root, key, value):
        """Insert a new key-value pair into the AVL tree rooted at 'root'."""
        if not root:
            return TreeNode(key, value)
        elif key < root.key:
            root.left = self.insert(root.left, key, value)
        elif key > root.key:
            root.right = self.insert(root.right, key, value)

        root.height = 1 + max(self.get_height(root.left), self.get_height(root.right))

        balance = self.get_balance(root)

        if balance > 1 and key < root.left.key:
            return self.right_rotate(root)

        if balance < -1 and key > root.right.key:
            return self.left_rotate(root)

        if balance > 1 and key > root.left.key:
            root.left = self.left_rotate(root.left)
            return self.right_rotate(root)

        if balance < -1 and key < root.right.key:
            root.right = self.right_rotate(root.right)
            return self.left_rotate(root)

        return root

    def search(self, root, key):
        """Search for a key in the AVL tree rooted at 'root' and return its value."""
        if root is None:
            return None
        elif root.key == key:
            return root.value
        elif root.key < key:
            return self.search(root.right, key)
        else:
            return self.search(root.left, key)

def fibonacci(n, root, avl):
    """Compute the nth Fibonacci number using memoization with an AVL tree."""
    if n <= 1:
        return n

    res = avl.search(root, n)
    if res is not None:
        return res

    res = fibonacci(n - 1, root, avl) + fibonacci(n - 2, root, avl)
    root = avl.insert(root, n, res)

    return res

# Test
avl = AVLTree()
root = None
result = fibonacci(10, root, avl)
print(result)
```

