def multiply_matrices(A, B):
    """Multiply two matrices A and B and return the resulting matrix."""
    return [[sum(a * b for a, b in zip(A_row, B_col)) for B_col in zip(*B)] for A_row in A]

def matrix_identity(size):
    """Generate an identity matrix of the given size."""
    return [[1 if i == j else 0 for j in range(size)] for i in range(size)]

def exponentiate_matrix(matrix, n=1):
    """Exponentiate the given matrix to the power of n and return the resulting matrix."""
    if n < 0:
        raise ValueError("Matrix exponentiation is not defined for negative powers.")

    size = len(matrix)
    if any(len(row) != size for row in matrix):
        raise ValueError("Matrix must be square.")

    result = matrix_identity(size)
    base = matrix

    while n > 0:
        if n % 2 == 1:
            result = multiply_matrices(result, base)
        base = multiply_matrices(base, base)
        n //= 2

    return result
