def recursive_search(numbers, target, left=0, right=None):
    """
    Perform a binary search on a sorted list to find the index of the target.

    :param numbers: List of sorted integers.
    :param target: Integer to search for in the list.
    :param left: Starting index for the search (default is 0).
    :param right: Ending index for the search (default is the last index of the list).
    :return: Index of the target if found, otherwise -1.
    """
    if right is None:
        right = len(numbers) - 1

    if left > right:
        return -1

    mid = (left + right) // 2

    if numbers[mid] == target:
        return mid
    elif numbers[mid] < target:
        return recursive_search(numbers, target, mid + 1, right)
    else:
        return recursive_search(numbers, target, left, mid - 1)
```

