import threading

class ConcurrentStorage:
    def __init__(self):
        self._storage = {}
        self._lock = threading.Lock()

    def store(self, key, value):
        """Stores a key-value pair in the storage system."""
        with self._lock:
            self._storage[key] = value

    def get(self, key, default=None):
        """Retrieves and removes the value associated with the key if it exists, otherwise returns the default value."""
        with self._lock:
            return self._storage.pop(key, default)

def get_from_storage(storage, key, default_value=None):
    """
    Retrieves the value associated with the key from the storage system if it exists, otherwise returns the default value.
    After retrieval, the key-value pair is removed from the storage system.
    """
    return storage.get(key, default_value)
