def multiply(a: int, b: int) -> int:
    """Helper function to multiply two integers using only addition."""
    result = 0
    negative_result = False

    if b < 0:
        negative_result = True
        b = -b

    for _ in range(b):
        result += a

    return -result if negative_result else result

def power(base: int, exponent: int) -> float:
    """Function to calculate the power of a number without using the exponentiation operator."""
    if exponent == 0:
        return 1
    elif exponent == 1:
        return base
    elif exponent < 0:
        return 1 / power(base, -exponent)
    else:
        result = base
        for _ in range(exponent - 1):
            result = multiply(result, base)
        return result
