class Library:
    def __init__(self):
        """Initialize an empty dictionary to store book titles and their availability."""
        self.books = {}

    def add_book(self, title):
        """Add a book to the library if it does not already exist. Mark it as available."""
        if title not in self.books:
            self.books[title] = True
            print(f"Book '{title}' added to the library.")
        else:
            print(f"Book '{title}' already exists in the library.")

    def borrow_book(self, title):
        """Borrow a book if it is available."""
        if title in self.books:
            if self.books[title]:
                self.books[title] = False
                print(f"Book '{title}' is now borrowed.")
            else:
                print(f"Book '{title}' is already borrowed.")
        else:
            print(f"Book '{title}' does not exist in the library.")

    def return_book(self, title):
        """Return a book and mark it as available if it was previously borrowed."""
        if title in self.books:
