```python
def value_mapper(value, input_min=None, input_max=None, output_min=None, output_max=None, mapping_segments=None):
    """
    Maps a given input value from one range to another.

    Parameters:
    - value: The input value to be mapped.
    - input_min: The minimum value of the input range (required for single-range mapping).
    - input_max: The maximum value of the input range (required for single-range mapping).
    - output_min: The minimum value of the output range (required for single-range mapping).
    - output_max: The maximum value of the output range (required for single-range mapping).
    - mapping_segments: A list of tuples defining multiple input and output ranges (required for multi-segment mapping).

    Returns:
    - The mapped value within the output range, or None if the value does not fall into any defined input range.
    """
    if mapping_segments:
        for input_range, output_range in mapping_segments:
            seg_input_min, seg_input_max = input_range
            seg_output_min, seg_output_max = output_range
            if seg_input_min <= value <= seg_input_max:
                return seg_output_min + (value - seg_input_min) * (seg_output_max - seg_output_min) / (seg_input_max - seg_input_min)
        return None
    else:
        if input_min is None or input_max is None or output_min is None or output_max is None:
            raise ValueError("input_min, input_max, output_min, and output_max must be provided if mapping_segments is not provided.")
        if input_min == input_max:
            raise ValueError("input_min and input_max cannot be the same.")
        return output_min + (value - input_min) * (output_max - output_min) / (input_max - input_min)
