def get_nested_value(data, *keys, default=None):
    """
    Safely retrieves a value from a deeply nested dictionary structure with support for lists and tuples,
    handling type mismatches and index out of range errors by returning the provided default value.

    :param data: A nested structure of dictionaries, lists, and tuples.
    :param keys: A variable number of keys or indices to traverse the nested structure.
    :param default: The value to return if the path is invalid or does not exist.
    :return: The value found at the specified path, or the default value if the path is invalid.
    """
    for key in keys:
        if isinstance(data, (dict, list, tuple)):
            if isinstance(data, dict) and key in data:
                data = data[key]
            elif isinstance(data, (list, tuple)) and isinstance(key, int) and 0 <= key < len(data):
                data = data[key]
            else:
                return default
        else:
            return default
    return data
