def calculate_progress(current_value, min_value, max_value):
    """
    Calculate the progress of current_value within the range [min_value, max_value].

    Parameters:
    current_value (float): The value whose progress is to be calculated.
    min_value (float): The minimum value of the range.
    max_value (float): The maximum value of the range.

    Returns:
    float: The progress of current_value within the range, as a float between 0.0 and 1.0.
    """
    if min_value == max_value:
        return 1.0 if current_value >= min_value else 0.0
    elif current_value <= min_value:
        return 0.0
    elif current_value >= max_value:
        return 1.0
    else:
        return (current_value - min_value) / (max_value - min_value)
