def calculate(value1, operator, value2):
    """
    Calculate the result of an arithmetic operation between two numbers.

    Args:
    value1: The first operand, can be any data type.
    operator: A string representing the arithmetic operation ('+', '-', '*', '/').
    value2: The second operand, can be any data type.

    Returns:
    The result of the arithmetic operation if valid, otherwise None.
    """
    try:
        value1 = float(value1)
        value2 = float(value2)

        if not (-1000 <= value1 <= 1000) or not (-1000 <= value2 <= 1000):
            return None

        if operator == '+':
            return value1 + value2
        elif operator == '-':
            return value1 - value2
        elif operator == '*':
            return value1 * value2
        elif operator == '/':
            if value2 == 0:
                return None
            return value1 / value2
        else:
            return None

    except ValueError:
        return None
