class Matrix:
    def __init__(self, data):
        """
        Initialize a Matrix object with a 2D list of integers.

        :param data: 2D list of integers representing the matrix.
        :raises ValueError: If the input is not a valid 2D list with consistent row lengths.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Data must be a 2D list with consistent row lengths.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def add(self, other):
        """
        Add another matrix to this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum of the two matrices.
        :raises ValueError: If the dimensions of the matrices are not the same.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtract another matrix from this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference of the two matrices.
        :raises ValueError: If the dimensions of the matrices are not the same.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiply this matrix by another matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product of the two matrices.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be the same as the number of rows in the second matrix.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def display(self):
        """
        Print the matrix in a readable format.
        """
        for row in self.data:
            print(" ".join(map(str, row)))
