def isValid(s: str) -> int:
    """
    Validates if the given string is a valid IPv4 address.

    :param s: A string representing the IPv4 address.
    :return: 1 if the string is a valid IPv4 address, 0 otherwise.
    """
    parts = s.split('.')

    if len(parts) != 4:
        return 0

    for part in parts:
        if not part.isdigit():
            return 0

        num = int(part)
        if num < 0 or num > 255:
            return 0

        if part != str(num):
            return 0

    return 1
