import logging

# Setting up basic configuration for logging
logging.basicConfig(level=logging.WARNING)

def validate_and_truncate_string(input_data, max_length, logging_enabled):
    """
    Processes a given data structure to ensure all strings do not exceed a specified maximum length.
    Truncates strings if necessary and logs warnings if logging is enabled.

    :param input_data: A string, list, tuple, or dictionary that may contain nested strings.
    :param max_length: An integer representing the maximum allowed length for any string.
    :param logging_enabled: A boolean indicating whether to log warnings when strings are truncated.
    :return: The processed data structure with all strings truncated to the maximum length if necessary.
    """
    def truncate_string(s, max_length, log):
        if len(s) > max_length:
            truncated = s[:max_length]
            if log:
                logging.warning(f"String truncated: {s} -> {truncated}")
            return truncated
        return s

    def process_data(data, max_length, log):
        if isinstance(data, str):
            return truncate_string(data, max_length, log)
        elif isinstance(data, list):
            return [process_data(item, max_length, log) for item in data]
        elif isinstance(data, tuple):
            return tuple(process_data(item, max_length, log) for item in data)
        elif isinstance(data, dict):
            return {key: process_data(value, max_length, log) for key, value in data.items()}
        else:
            return data

    return process_data(input_data, max_length, logging_enabled)
