import threading

class DataStream:
    def __init__(self):
        self.lock = threading.Lock()
        self.is_open = False

    def open(self) -> bool:
        with self.lock:
            if not self.is_open:
                self.is_open = True
                print("Connection opened.")
                return True
            else:
                print("Connection is already open.")
                return False

    def send(self, data: str) -> bool:
        with self.lock:
            if self.is_open:
                print(f"Data sent: {data}")
                return True
            else:
                print("Cannot send data: Connection is not open.")
                return False

    def close(self) -> bool:
        with self.lock:
            if self.is_open:
                self.is_open = False
                print("Connection closed.")
                return True
            else:
                print("Connection is already closed.")
                return False

