import threading
from functools import wraps

class OncePerObjectPerStep:
    def __init__(self):
        # Dictionary to keep track of which objects have been called per step
        self.steps = {}
        # Lock to ensure thread safety when checking and updating the dictionary
        self.lock = threading.Lock()

    def __call__(self, func):
        @wraps(func)
        def wrapper(obj, step, *args, **kwargs):
            with self.lock:
                # Check if the current object and step are not in the dictionary
                if (id(obj), step) not in self.steps:
                    result = func(obj, step, *args, **kwargs)
                    # Mark the current object and step as executed
                    self.steps[(id(obj), step)] = result
                    return result
                else:
                    # Function has already been called for this object and step, return cached result
                    return self.steps[(id(obj), step)]
        return wrapper

# Usage example:
class ExampleClass:
    def __init__(self):
        self.x = [1, 2, 3]

    @OncePerObjectPerStep()
    def process_step(self, step, factor):
        """
        Processes a step by multiplying each element in self.x by the given factor.
        Ensures that each step is processed only once per object.

        :param step: A string representing the step to be processed.
        :param factor: A number by which each element in self.x will be multiplied.
        :return: The updated list self.x.
        """
        self.x = [value * factor for value in self.x]
        print(f"Processed step {step} with factor {factor}, new x: {self.x}")
        return self.x
