def calculator(operation: str, a: float, b: float) -> float:
    """
    Perform a basic arithmetic operation on two numbers with error handling.

    Parameters:
    operation (str): The arithmetic operation to perform ("add", "subtract", "multiply", "divide").
    a (float): The first operand.
    b (float): The second operand.

    Returns:
    float: The result of the arithmetic operation, or None if an error occurs.
    """
    try:
        if operation == "add":
            return a + b
        elif operation == "subtract":
            return a - b
        elif operation == "multiply":
            return a * b
        elif operation == "divide":
            if b == 0:
                raise ValueError("Cannot divide by zero.")
            return a / b
        else:
            raise ValueError("Invalid operation.")
    except TypeError:
        print("Error: Both a and b must be numbers.")
    except ValueError as e:
        print(f"Error: {e}")
    return None
