import threading

class NodeDatabase:
    def __init__(self):
        self._nodes = {}
        self._lock = threading.Lock()

    def add_node(self, node_id, node_level):
        """
        Adds a new node to the database.
        If the node already exists, prints a message indicating that the node already exists.
        """
        with self._lock:
            if node_id in self._nodes:
                print(f"Node with ID {node_id} already exists. Use update_node to change its level.")
            else:
                self._nodes[node_id] = (node_id, node_level)
                print(f"Node with ID {node_id} and level {node_level} added.")

    def update_node(self, node_id, node_level):
        """
        Updates the level of an existing node.
        If the node does not exist, prints a message indicating that the node does not exist.
        """
        with self._lock:
            if node_id in self._nodes:
                self._nodes[node_id] = (node_id, node_level)
                print(f"Node with ID {node_id} updated to level {node_level}.")
            else:
                print(f"Node with ID {node_id} not found. Use add_node to add it.")

    def delete_node(self, node_id):
        """
        Deletes a node from the database.
        If the node does not exist, prints a message indicating that the node does not exist.
        """
        with self._lock:
            if node_id in self._nodes:
                del self._nodes[node_id]
                print(f"Node with ID {node_id} deleted.")
            else:
                print(f"Node with ID {node_id} not found.")

    def __str__(self):
        return '\n'.join(f"{node_id}: {node_level}" for node_id, (_, node_level) in self._nodes.items())

def worker(op, db, *args):
    if op == 'add':
        db.add_node(*args)
    elif op == 'update':
        db.update_node(*args)
    elif op == 'delete':
        db.delete_node(*args)

if __name__ == '__main__':
    db = NodeDatabase()
    threads = []

    operations = [
        ('add', 1, 10),
        ('add', 2, 20),
        ('update', 1, 15),
        ('delete', 2),
        ('add', 3, 25),
        ('delete', 4)
    ]

    for op in operations:
        t = threading.Thread(target=worker, args=(op[0], db, *op[1:]))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    print("Final database state:")
    print(db)
```

