            raise ValueError("Both operands must be int or float.")
        return a + b

    def subtract(self, a, b):
        """Return the difference of a and b. Raises ValueError if operands are not int or float."""
        if not all(isinstance(i, (int, float)) for i in [a, b]):
            raise ValueError("Both operands must be int or float.")
        return a - b

    def multiply(self, a, b):
        """Return the product of a and b. Raises ValueError if operands are not int or float."""
        if not all(isinstance(i, (int, float)) for i in [a, b]):
            raise ValueError("Both operands must be int or float.")
        return a * b

    def divide(self, a, b):
        """Return the division of a by b. Raises ValueError if operands are not int or float or if b is zero."""
