class Employee:
    def __init__(self, salary):
        self.salary = salary

    def get_salary(self):
        """
        Returns the salary of the employee.

        :return: The salary of the employee.
        """
        return self.salary

    def compute_bonus(self, performance_rating):
        """
        Computes the bonus amount based on the employee's performance rating.

        :param performance_rating: An integer between 1 and 5 representing the performance rating.
        :return: The bonus amount as a float.
        :raises ValueError: If the performance rating is not between 1 and 5.
        """
        if performance_rating == 1:
            bonus_percentage = 0
        elif performance_rating == 2:
            bonus_percentage = 10
        elif performance_rating == 3:
            bonus_percentage = 20
        elif performance_rating == 4:
            bonus_percentage = 40
        elif performance_rating == 5:
            bonus_percentage = 60
        else:
            raise ValueError("Performance rating should be between 1 and 5.")

        bonus_amount = (bonus_percentage / 100) * self.get_salary()
        return bonus_amount
