{"code":"def routes(n):
    if n < 1:
        return 0

    grid = [[0] * (n+1) for _ in range(n+1)]

    # Base case
    grid[0][0] = 1

    for i in range(1, n+1):
        grid[i][0] = 1
        grid[0][i] = 1

    for i in range(1, n+1):
        for j in range(1, n+1):
            grid[i][j] = grid[i-1][j] + grid[i][j-1]

    return grid[n][n]"}

