{"code":"def dig_pow(n, p):
    # Convert n to a string
    n_str = str(n)

    # Calculate the sum of digits raised to the power of p plus their position
    digit_sum = 0
    for i, digit in enumerate(n_str):
        digit_sum += int(digit) ** (p + i)

    # Check if the sum is divisible by n
    if digit_sum % n == 0:
        return digit_sum // n
    else:
        return -1"}

